const ExcelJS = require('exceljs');
async function run() {
  const workbook = new ExcelJS.Workbook();
  const filePath = 'C:\\\\Users\\\\lg\\\\Desktop\\\\오늘\\\\(데이터검증팀)실사 DB 취합_전달용_260720_배현명.xlsx';
  await workbook.xlsx.readFile(filePath);
  const sheet = workbook.getWorksheet('기업 정보');

  const headers = [];
  sheet.getRow(1).eachCell({ includeEmpty: true }, (c, col) => {
    headers[col] = c.value;
  });
  console.log('Headers count:', headers.length);
  console.log('Headers:', headers.filter(Boolean));

  let totalDataRows = 0;
  const authorCounts = {};

  for (let r = 2; r <= sheet.rowCount; r++) {
    const row = sheet.getRow(r);
    const author = row.getCell(1).value;
    const company = row.getCell(3).value;
    const bizno = row.getCell(4).value;
    if (!author && !company && !bizno) continue;

    totalDataRows++;
    const authKey = String(author || '미지정').trim();
    authorCounts[authKey] = (authorCounts[authKey] || 0) + 1;
  }

  console.log('Total non-empty data rows:', totalDataRows);
  console.log('Author counts:', authorCounts);
}
run().catch(console.error);
